# For each troubled symbol, compute average daily volume in 2008 (non-null)
results = []
for _, row in troubled.iterrows():
    sym = row['Symbol']
    if sym not in table_names:
        continue
    try:
        q = f'SELECT AVG(Volume) AS avg_vol, COUNT(Volume) AS n FROM "{sym}" WHERE Volume IS NOT NULL AND Date >= \'2008-01-01\' AND Date <= \'2008-12-31\''
        r = con_trade.execute(q).fetchone()
        avg_vol, n = r
        if n and n > 0 and avg_vol is not None:
            results.append((sym, row['Company Description'], avg_vol, n))
    except Exception as e:
        print(sym, e)

print(len(results))
for r in results:
    print(r[0], r[2], r[3])

# Print full descriptions for the 15 results
for sym, desc, avg_vol, n in results:
    print(sym, "::", desc[:120])

import re

def extract_company_name(desc):
    # Take everything up to first occurrence of " specializes", " provides", " is ", " harnesses", " offers", ", based"
    # Easiest: split on the first period that follows the company suffix (Inc., Corp., Corporation, Ltd., LP)
    # Use regex to capture up to and including common suffix
    m = re.match(r'^(.+?(?:Inc\.|Corporation|Corp\.|Co\.,\s*Ltd\.|Ltd\.|LP|Group Inc\.|Holdings|Technologies, Inc\.|Pharma Corp\.))', desc)
    if m:
        return m.group(1).strip().rstrip(',')
    # fallback: split on first 'specializes'
    return desc.split(' specializes')[0].split(' provides')[0].split(' is ')[0].split(' harnesses')[0].strip()

final = []
for sym, desc, avg_vol, n in results:
    name = extract_company_name(desc)
    final.append((name, avg_vol))
    print(f"{name}: {avg_vol}")

# Final output format: dict/list of (name, avg_vol)
out = {name: avg_vol for name, avg_vol in final}
print(out)
